/* Plain-language "Qué significa esto" sentences, generated by rules (no external service, no causes). */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) {
    module.exports = factory(require('./format.js'));
  } else {
    root.ZE = root.ZE || {};
    Object.assign(root.ZE, factory(root.ZE));
  }
}(typeof self !== 'undefined' ? self : this, function (F) {
  'use strict';
  const n1 = F.fmtNum;
  const dia = function (d) { return F.fmtDate(d.fecha) + (d.tema ? ' (' + d.tema + ')' : ''); };

  /** Sentences about the whole course. Every figure quoted is visible in the same view. */
  function cursoInsights(res) {
    const out = [];
    const c = res.cohorte;
    if (!c.n) return out;
    const diasConDatos = res.dias.filter(function (d) { return d.promedio !== null; });
    out.push('Se evaluó a ' + c.n + (c.n === 1 ? ' alumno' : ' alumnos') + ' en ' + diasConDatos.length + (diasConDatos.length === 1 ? ' día' : ' días') + '; el rendimiento promedio del curso es ' + n1(c.promedio) + ' (mediana ' + n1(c.mediana) + ').');
    if (diasConDatos.length >= 2) {
      const sorted = diasConDatos.slice().sort(function (a, b) { return b.promedio - a.promedio; });
      const hi = sorted[0];
      const lo = sorted[sorted.length - 1];
      out.push('El día con mayor promedio fue el ' + dia(hi) + ' (' + n1(hi.promedio) + ') y el de menor promedio el ' + dia(lo) + ' (' + n1(lo.promedio) + ').');
    }
    const withData = res.metricas.filter(function (m) { return m.pctAlcanzan !== null; });
    if (withData.length >= 2) {
      const sorted = withData.slice().sort(function (a, b) { return b.pctAlcanzan - a.pctAlcanzan; });
      const hi = sorted[0];
      const lo = sorted[sorted.length - 1];
      out.push('La métrica con mayor cumplimiento de su mínimo es «' + hi.nombre + '» (' + n1(hi.pctAlcanzan, 0) + ' % de los alumnos) y la de menor cumplimiento es «' + lo.nombre + '» (' + n1(lo.pctAlcanzan, 0) + ' %).');
    }
    if (c.asistenciaPromedio !== null) out.push('La asistencia promedio es ' + n1(c.asistenciaPromedio, 0) + ' % de los días de clases.');
    if (c.incompletos > 0) {
      out.push(c.incompletos + (c.incompletos === 1 ? ' alumno tiene' : ' alumnos tienen') + ' evaluación incompleta: su puntaje considera solo las métricas ya evaluadas.');
    }
    return out;
  }

  /** Sentences about one student. */
  function alumnoInsights(a, res) {
    const out = [];
    const diasPunt = a.dias.filter(function (d) { return d.total !== null; });
    if (a.final === null) {
      out.push('Todavía no tiene puntajes registrados.');
      return out;
    }
    out.push('Su rendimiento final es ' + n1(a.final) + ', el promedio de ' + diasPunt.length + (diasPunt.length === 1 ? ' día evaluado.' : ' días evaluados.'));
    if (res && res.puntosBase > 0) out.push('El puntaje de cada día parte de una base de ' + n1(res.puntosBase, 0) + ' puntos.');
    out.push('Alcanza el mínimo en ' + a.metricasAlcanzadas + ' de ' + a.metricasEvaluadas + (a.metricasEvaluadas === 1 ? ' métrica evaluada.' : ' métricas evaluadas.'));
    const conProm = a.metricas.filter(function (m) { return m.promedioNorm !== null; });
    if (conProm.length >= 2) {
      const sorted = conProm.slice().sort(function (x, y) { return x.promedioNorm - y.promedioNorm; });
      const lo = sorted[0];
      if (lo.promedioNorm < 100 - 1e-9) {
        out.push(lo.tipo === 'checklist' ? 'Su métrica con menor cumplimiento es «' + lo.nombre + '» (cumplió en ' + n1(lo.promedioNorm, 0) + ' % de las veces evaluadas).' : 'Su métrica con menor puntaje es «' + lo.nombre + '» (' + n1(lo.promedioNorm) + ' de 100).');
      } else {
        out.push('Cumplió o alcanzó el máximo en todas las métricas evaluadas.');
      }
    }
    out.push('Asistió ' + a.asistencia.presentes + ' de ' + a.asistencia.total + ' días (' + n1(a.asistencia.pct, 0) + ' %).');
    if (a.parcial) out.push('La evaluación es parcial: cubre ' + n1(a.cobertura, 0) + ' % de las métricas en los días que asistió.');
    if (diasPunt.length >= 2) {
      const f = diasPunt[0];
      const l = diasPunt[diasPunt.length - 1];
      const diff = l.total - f.total;
      const verb = Math.abs(diff) < 2 ? 'se mantuvo en torno a' : diff > 0 ? 'subió de ' + n1(f.total) + ' a' : 'bajó de ' + n1(f.total) + ' a';
      out.push('Su total diario ' + verb + ' ' + n1(l.total) + ' entre el ' + F.fmtDate(f.fecha) + ' y el ' + F.fmtDate(l.fecha) + '.');
    }
    return out;
  }

  return { cursoInsights: cursoInsights, alumnoInsights: alumnoInsights };
}));
